#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <msi.h>
#include <unknwn.h>
#include <shellapi.h>
#include <wchar.h>
#include <string.h>
#include "wix5/BootstrapperApplicationTypes.h"
